// Biomedical Equipment Technician Practice Test 1. Original questions written for Valus from the HOSA
// 2026–27 test plan, slightly harder than the sample items: device principles, electrical safety
// calculations, regulations and troubleshooting. Content follows the Valus BET lessons.
import {q, mix} from './q.js';
const MET='HOSA–CBET Medical Equipment Technician (MET) 100 Series', AAMI='AAMI BMET 101', FDA='FDA Center for Devices and Radiological Health';
const AP='Anatomy & Physiology', DEV='Medical Devices as Related to Public Safety', SAFE='Safety in Healthcare', ELEC='Fundamentals in Electricity and Electronics', REAS='Reasoning', IT='Healthcare IT';

export default {
 id:'biomedical-equipment-technician-1',
 event:'Biomedical Equipment Technician',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'the AAMI BMET 101 and CBET Medical Equipment Technician (MET) 100 courses, with FDA device regulations',
 plan:[{area:AP,weight:10},{area:DEV,weight:22},{area:SAFE,weight:16},{area:ELEC,weight:14},{area:REAS,weight:24},{area:IT,weight:14}],
 questions:mix([
  q(AP,'Where does the heart’s normal electrical impulse begin?','The SA node',['The AV node','The bundle of His','The Purkinje fibers'],'B','The impulse starts in the sinoatrial node, then travels through the AV node, bundle of His, bundle branches and Purkinje fibers.',MET),
  q(AP,'Which device records the electrical activity of skeletal muscles?','EMG',['EEG','ECG','EOG'],'D','Electromyography records muscle activity, EEG records brain activity and ECG records heart activity.',MET),
  q(AP,'In a blood pressure reading of 120/80 mm Hg, what does 120 represent?','Pressure during ventricular contraction',['Pressure during ventricular relaxation','Mean pressure across the cardiac cycle','Pressure in the right atrium at rest'],'A','Systolic pressure occurs during ventricular contraction; diastolic pressure (80) occurs during relaxation.',MET),
  q(AP,'Where in the lungs does gas exchange take place?','The alveoli',['The trachea','The bronchi','The pleura'],'C','Oxygen moves into the capillaries and carbon dioxide moves out across the thin alveolar walls.',MET),
  q(AP,'A patient lying face down is in which position?','Prone',['Supine','Fowler’s','Lateral'],'B','Supine is face up. Positioning terms help BMETs understand clinical setups such as imaging tables.',MET),
  q(DEV,'Which FDA center regulates medical devices?','CDRH',['CDER','CBER','CFSAN'],'D','The Center for Devices and Radiological Health regulates devices under the Food, Drug, and Cosmetic Act and the Medical Device Amendments of 1976.',FDA),
  q(DEV,'Most moderate-risk (Class II) devices reach the market through a 510(k). What must it show?','Substantial equivalence to a legal device',['Clinical trial proof of superiority','Approval from each state health board','That no similar device is marketed'],'A','Class III devices usually require premarket approval (PMA) with clinical evidence of safety and effectiveness.',FDA),
  q(DEV,'Which device class carries the highest risk and usually requires premarket approval?','Class III',['Class I','Class II','Class IV'],'C','Implantable pacemakers and defibrillators are examples of Class III devices, which sustain or support life.',FDA),
  q(DEV,'Under Medical Device Reporting rules, a hospital learns a device contributed to a patient’s death. To whom must it report, and how fast?','The FDA and maker within 10 work days',['The maker only within 30 work days','The FDA only within one calendar year','The state board only within 5 work days'],'B','Device-related serious injuries go to the manufacturer (or the FDA if unknown) within 10 work days, and an annual summary goes to the FDA.',FDA),
  q(DEV,'Which FDA database can BMETs search for reports of device problems?','MAUDE',['PubMed','NHSN','CODIS'],'D','The Manufacturer and User Facility Device Experience database helps identify patterns of device failures.',FDA),
  q(DEV,'What does the Unique Device Identification (UDI) system mainly improve?','Device tracking and recalls',['Device battery service life','Accuracy of patient billing','Staff credential verification'],'A','A UDI code on the label lets facilities quickly find affected devices when recalls or safety alerts occur.',FDA),
  q(DEV,'Smart infusion pumps use dose error reduction software with a drug library. What is a “hard limit”?','A dose limit that cannot be overridden',['A dose warning a nurse may override','A limit on the pump’s battery runtime','A maximum size for the IV bag hung'],'C','Soft limits warn but can be overridden; hard limits block programming errors that could be dangerous.',AAMI),
  q(DEV,'An infusion pump alarms “downstream occlusion.” What is a likely cause?','A kinked line between pump and patient',['An empty IV bag above the pump','A closed roller clamp above the pump','An air bubble at the top of the bag'],'B','Downstream occlusions are between the pump and the patient. An empty bag or closed upstream clamp causes an upstream occlusion.',AAMI),
  q(DEV,'Why is synchronized cardioversion timed to the R wave?','A shock on the T wave may cause VF',['It makes the shock far less painful','It conserves the device’s battery','It is used only on pulseless rhythms'],'D','Unsynchronized defibrillation is used for VF and pulseless VT; synchronized cardioversion treats unstable tachycardias with a pulse.',AAMI),
  q(DEV,'In monopolar electrosurgery, what does the return electrode contact quality monitor do?','Stops output if pad contact is poor',['Raises power when tissue resists','Measures blood loss during surgery','Cools the active electrode tip'],'C','Poor contact concentrates current under the pad and can cause burns, so the unit stops output until contact is restored.',AAMI),
  q(DEV,'In MRI safety, which zone is the scanner room itself?','Zone IV',['Zone I','Zone II','Zone III'],'B','Zone I is public, Zone II is screening, Zone III is restricted and Zone IV contains the magnet.',AAMI),
  q(SAFE,'Why is microshock more dangerous than macroshock at the same current?','Current reaches the heart directly',['It occurs at a much higher voltage','It must first cross the dry skin','It lasts only a few microseconds'],'A','Currents as small as microamperes can cause fibrillation if they reach the heart through a catheter or pacing wire.',AAMI),
  q(SAFE,'Which applied-part type is required for devices connected directly to the heart?','CF',['B','BF','A'],'C','CF (cardiac floating) is the strictest classification, with the lowest allowed leakage current.',AAMI),
  q(SAFE,'What does a ground-fault circuit interrupter (GFCI) detect?','Unequal hot and neutral current',['Line voltage above 130 volts','A weak internal backup battery','Overheating from a blocked vent'],'B','A difference of about 4–6 mA means current is leaking to ground, possibly through a person, so the GFCI trips.',AAMI),
  q(SAFE,'What is the purpose of lockout/tagout (LOTO)?','Keeping equipment de-energized in service',['Tracking equipment loaned to other units','Labeling devices under an FDA recall','Securing patients’ personal belongings'],'D','LOTO isolates energy sources and labels them so equipment cannot start while it is being repaired.',AAMI),
  q(SAFE,'Which three principles reduce exposure to ionizing radiation under ALARA?','Time, distance and shielding',['Speed, height and filtration','Voltage, current and resistance','Dose, density and dwell'],'A','Minimize time near the source, maximize distance and use shielding such as lead aprons.',AAMI),
  q(SAFE,'A fire starts in an equipment room. In RACE, what is the first step?','Rescue',['Alarm','Contain','Extinguish'],'C','RACE is Rescue, Alarm, Contain, then Extinguish if safe or evacuate. PASS describes extinguisher use.',AAMI),
  q(SAFE,'A device arrives for repair visibly soiled with blood. What should the BMET do?','Send it back for decontamination',['Wipe it with water, then repair it','Repair it now and clean it afterward','Repair it after removing gloves'],'B','Standard precautions require equipment to be cleaned and decontaminated before it is serviced.',AAMI),
  q(SAFE,'What do red electrical receptacles indicate in many hospitals?','Generator-backed emergency power',['Isolated power for the MRI suite','Outlets that are out of service','Outlets for computer networks only'],'D','Critical equipment is plugged into emergency power so it keeps running during a utility outage.',AAMI),
  q(ELEC,'A 120-V circuit has 60 Ω of resistance. Using Ohm’s law, what is the current?','2 A',['0.5 A','60 A','7,200 A'],'B','By Ohm’s law, I = V ÷ R, so the current is 120 V ÷ 60 Ω = 2 A.',AAMI),
  q(ELEC,'A device draws 2 A from a 120-V outlet. How much power does it use?','240 W',['60 W','122 W','480 W'],'D','Electrical power is P = V × I, so the device uses 120 V × 2 A = 240 W.',AAMI),
  q(ELEC,'What are the nominal voltage and frequency of standard U.S. wall power?','120 V at 60 Hz',['220 V at 50 Hz','170 V at 50 Hz','240 V at 60 Hz'],'A','The 120 V figure is an RMS value; the actual peak voltage of the sine wave is about 170 V.',AAMI),
  q(ELEC,'How should a multimeter be connected to measure current?','In series with the circuit',['In parallel across the part','Across the outlet terminals','With all power removed first'],'C','The circuit is broken so current flows through the meter. Voltage is measured in parallel, and resistance with power off.',AAMI),
  q(ELEC,'What does a rectifier in a power supply do?','Converts AC to DC',['Converts DC to AC','Steps up voltage','Stores the charge'],'B','Diodes rectify AC into pulsating DC; capacitors filter it and a regulator holds the DC voltage steady.',AAMI),
  q(ELEC,'Kirchhoff’s current law states that:','Current in equals current out at a node',['Loop voltage drops exceed the source','Resistances add when placed in parallel','Power equals voltage times resistance'],'D','Kirchhoff’s voltage law states that voltage drops around a closed loop add up to the source voltage.',AAMI),
  q(ELEC,'An RC circuit has R = 10 kΩ and C = 100 µF. What is the time constant?','1 second',['0.1 second','10 seconds','100 seconds'],'A','τ = R × C = 10,000 Ω × 0.0001 F = 1 s. The capacitor charges about 63% in one time constant.',AAMI),
  q(REAS,'A patient monitor shows a wavy, wandering ECG baseline, but the patient is stable. What is the most likely cause?','Poor electrode contact or motion',['A failing internal power supply','A corrupted firmware update','A cracked display panel'],'C','Baseline wander usually comes from electrode problems or breathing movement. Check skin prep and electrode placement first.',MET),
  q(REAS,'An ECG trace shows regular, fine 60-Hz interference. What is a likely source?','Nearby equipment or a poor ground',['Patient shivering under blankets','Electrodes with too much fresh gel','A nearly depleted backup battery'],'B','AC interference is often caused by poor grounding or nearby cords. Notch filters and proper grounding reduce it.',MET),
  q(REAS,'A pulse oximeter shows a low reading on a patient who looks well and is wearing dark nail polish. What should be done first?','Reposition the probe and recheck',['Replace the monitor immediately','Call a rapid response team','Raise the low-SpO₂ alarm limit'],'D','Nail polish, motion, cold fingers and bright light commonly cause false readings.',MET),
  q(REAS,'A noninvasive blood pressure monitor gives falsely high readings. Which cause should be checked?','A cuff too small for the arm',['A cuff too large for the arm','The patient lying very still','The arm held at heart level'],'A','A cuff that is too small reads high; one that is too large reads low.',MET),
  q(REAS,'A ventilator gives a low-pressure alarm. What should be suspected first?','A circuit leak or disconnection',['Secretions blocking the airway','The patient biting the tube','Decreased lung compliance'],'C','Low-pressure alarms suggest leaks or disconnections, an emergency. High-pressure alarms suggest obstruction.',MET),
  q(REAS,'A device will not power on. What is the most logical first troubleshooting step?','Check the cord, outlet and fuse',['Replace the main circuit board','Reinstall the operating firmware','Order a replacement device'],'B','Start with the simplest, most likely causes before opening the device or replacing expensive parts.',MET),
  q(REAS,'An invasive arterial pressure reading is suddenly much higher after the patient’s bed is raised. What is the likely cause?','The transducer is below heart level',['The patient’s pressure truly rose','The transducer cable came unplugged','The monitor battery is running low'],'D','Transducers must be leveled at the phlebostatic axis and zeroed. A transducer below the heart reads falsely high.',MET),
  q(REAS,'Several nurses report that the same model of infusion pump shuts off unexpectedly. What should the BMET do besides repairing the pumps?','Check MAUDE and maker notices',['Treat each failure as unrelated','Discard every pump of that model','Ask nurses to stop filing reports'],'A','Patterns across devices may indicate a design issue or recall; reporting and research protect other patients.',FDA),
  q(REAS,'Why do BMETs help configure monitor alarm limits?','To reduce alarm fatigue',['So alarms can be silenced permanently','Because more alarms always add safety','Because limits are fixed at the factory'],'C','Desensitized staff may miss important alarms; appropriate limits make alarms meaningful.',MET),
  q(REAS,'A defibrillator fails its delivered-energy test into a 50-Ω load. What should happen?','Remove it from service for repair',['Return it to use with a warning note','Lower the test energy until it passes','Retest it at the next annual check'],'B','A defibrillator that does not deliver accurate energy could fail a patient; it must not be used until repaired and verified.',MET),
  q(REAS,'After repairing a patient-connected device, what must be performed before returning it to service?','Electrical safety and performance tests',['A new purchase order and asset tag','A renewal of the software license','A satisfaction survey of the users'],'D','Leakage current and function are verified after repairs, at incoming inspection and on a schedule.',AAMI),
  q(REAS,'A unit’s monitor reads normally on a simulator but not on patients. What should the BMET suspect?','The patient leads, cables or sensors',['A failure of the main processor board','An unstable building power supply','An expired software license key'],'C','If the monitor works with a simulator, the fault likely lies in parts between the patient and the monitor.',MET),
  q(IT,'What is a computerized maintenance management system (CMMS) used for?','Tracking inventory and work orders',['Billing patients for procedures','Storing and viewing medical images','Scheduling operating room cases'],'B','The CMMS supports recall searches, preventive maintenance and regulatory documentation.',MET),
  q(IT,'Which standard is used to store and transmit medical images, such as CT and MRI studies?','DICOM',['HL7','ICD-10','CPT'],'D','DICOM governs imaging data and communication between imaging modalities and the PACS.',MET),
  q(IT,'Why do many hospitals place medical devices on a separate network segment?','To contain cyberattacks',['To speed up device charging','To remove password needs','To reduce printer traffic costs'],'A','Network segmentation reduces the attack surface and isolates vulnerable devices from the rest of the network.',AAMI),
  q(IT,'Why must software patches for networked medical devices be coordinated with the manufacturer?','Untested patches may affect safety',['Patches are never actually needed','Makers forbid all security updates','Patches change only screen colors'],'C','Validated updates protect cybersecurity without compromising device function or regulatory clearance.',AAMI),
  q(IT,'Which messaging standard commonly connects devices and systems to the electronic health record?','HL7',['DICOM','Bluetooth','Zigbee'],'B','HL7 messages carry orders, results and device data between clinical information systems.',MET),
  q(IT,'Which document describes a device’s security features to help hospitals assess cybersecurity risk?','MDS2 form',['Safety Data Sheet','510(k) letter','Warranty card'],'D','The Manufacturer Disclosure Statement for Medical Device Security lists features such as encryption and authentication.',AAMI),
  q(IT,'What is the main benefit of integrating infusion pumps with the EHR?','Fewer manual programming errors',['Pumps no longer need maintenance','Nurses no longer verify orders','Pumps can run without power'],'A','Auto-programming from the order reduces manual entry errors, though staff still verify settings.',AAMI)
 ],223)
};
